import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    if n <= 0:
        return
    lines = []
    for i in range(1, n + 1):
        num = n - i + 1
        if i == 1:
            lines.append(str(num) + " ")
        else:
            lines.append(str(num) * i)
    sys.stdout.write("\n".join(lines))

if __name__ == "__main__":
    main()
